import { Fieldset } from '@absoluteui/components/fieldset';
import { TextInput } from '@absoluteui/components/text-input';
import { Button } from '@absoluteui/components/button';

const element = document.createElement('fieldset');
const streetHost = document.createElement('div');
const cityHost = document.createElement('div');
element.append(streetHost, cityHost);
const check = document.createElement('button');
check.type = 'button';
check.textContent = 'Check address';
Button.enhance(check);
document.body.append(element, check);
const street = TextInput.create(streetHost, { label: 'Street', autocomplete: 'address-line1' });
const city = TextInput.create(cityHost, { label: 'City', autocomplete: 'address-level2' });
const address = Fieldset.enhance(element, { legend: 'Delivery address', description: 'Where we send the order', required: true });
check.addEventListener('click', () => {
  const missing = street.value.trim() === '' || city.value.trim() === '';
  address.update({ error: missing ? 'Enter a street and a city' : null });
  if (missing) address.focus();
});
